#!/usr/bin/env python3
"""Focused differential harness for the httpd mod_http2 request_headers_failed fix.

Extracts the *actual* functions (set_error_response, h2_stream_add_header,
on_header_cb) from a checkout's modules/http2 sources and compiles them against a
minimal mock prelude. This exercises the real target/patched code paths:

  * positive path:     successful header adds keep the callback returning 0
  * vulnerable path:   repeated failed adds with an error status set
  * no-rtmp path:      failure without an assembled request bails immediately

Usage:
  make_harness.py --srcdir <checkout> --out <harness.c>
"""
from __future__ import annotations

import argparse
import sys
from pathlib import Path


def scan_balanced(text: str, start: int) -> int:
    """Return index just past the matching close brace of the block beginning at start."""
    depth = 0
    i = start
    n = len(text)
    while i < n:
        c = text[i]
        if c == '/' and i + 1 < n and text[i + 1] == '/':
            j = text.find('\n', i)
            i = n if j < 0 else j + 1
            continue
        if c == '/' and i + 1 < n and text[i + 1] == '*':
            j = text.find('*/', i + 2)
            i = n if j < 0 else j + 2
            continue
        if c == '"' or c == "'":
            quote = c
            i += 1
            while i < n:
                if text[i] == '\\':
                    i += 2
                    continue
                if text[i] == quote:
                    i += 1
                    break
                i += 1
            continue
        if c == '{':
            depth += 1
        elif c == '}':
            depth -= 1
            if depth == 0:
                return i + 1
        i += 1
    raise ValueError('unbalanced braces')


def extract_function(text: str, signature: str) -> str:
    idx = text.find(signature)
    if idx < 0:
        raise ValueError(f'signature not found: {signature}')
    brace = text.find('{', idx)
    if brace < 0:
        raise ValueError(f'no opening brace for {signature}')
    end = scan_balanced(text, brace)
    return text[idx:end]


PRELUDE = r'''
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdarg.h>

typedef int apr_status_t;
#define APR_SUCCESS 0
#define APR_EINVAL 22
#define APR_ECONNRESET 104
#define APR_INT32_MAX 2147483647

#define H2_HTTP_STATUS_UNSET (0)
#define HTTP_REQUEST_URI_TOO_LARGE 414
#define HTTP_REQUEST_HEADER_FIELDS_TOO_LARGE 431
#define HTTP_BAD_REQUEST 400
#define HTTP_NOT_IMPLEMENTED 501

#define NGHTTP2_ERR_TEMPORAL_CALLBACK_FAILURE (-521)
#define NGHTTP2_ERR_TEMPORAL_CALLBACK_FAILURE_ 0

#define H2_SS_IDLE 0
#define H2_SS_OPEN 1
#define H2_SS_CLOSED 2

#define H2_STRM_MAGIC_OK 0x42424242
#define H2_STRM_ASSERT_MAGIC(s, m) do { } while (0)

#define APLOG_MARK __FILE__, __LINE__
#define APLOGNO(n) n
#define APLOG_DEBUG 7
#define APLOG_INFO 6
#define APLOG_TRACE1 2
#define APLOG_TRACE2 1

#define H2MIN(a, b) ((a) < (b) ? (a) : (b))
#define H2_STRM_LOG(n, s, ...) n
#define H2_STRM_MSG(s, ...) __VA_ARGS__
#define H2_SSSN_STRM_MSG(s, id, ...) __VA_ARGS__

#define H2_ERR_ENHANCE_YOUR_CALM 0x0b
#define H2_SEV_CANCELLED 2

struct h2_config {
    int limit_req_line;
    int limit_req_fields;
    int limit_req_fieldsize;
};

struct h2_request {
    int http_status;
};

typedef struct h2_session {
    struct h2_config *s;
    void *c1;
} h2_session;

typedef struct h2_stream {
    int id;
    void *pool;
    h2_session *session;
    int state;
    int request_headers_added;
    int request_headers_failed;
    struct h2_request *rtmp;
    void *response;
} h2_stream;

typedef struct nghttp2_session nghttp2_session;
typedef struct {
    struct { int stream_id; } hd;
} nghttp2_frame;

/* ---- controllable mock behaviour ---- */
static int g_add_header_status = APR_EINVAL;   /* fail adds by default */
static int g_request_create_null = 0;          /* make h2_request_create return NULL */
static h2_stream *g_stream = NULL;

static void ap_log_cerror(const char *file, int line, int level, apr_status_t status,
                          void *c, ...)
{
    (void)file; (void)line; (void)level; (void)status; (void)c;
}

static h2_stream *get_stream(h2_session *session, int stream_id)
{
    (void)session; (void)stream_id;
    return g_stream;
}

static struct h2_request *h2_request_create(int id, void *pool, void *a, void *b,
                                            void *c, void *d, void *e)
{
    (void)id; (void)pool; (void)a; (void)b; (void)c; (void)d; (void)e;
    if (g_request_create_null) {
        return NULL;
    }
    return (struct h2_request *)calloc(1, sizeof(struct h2_request));
}

static apr_status_t h2_request_add_header(struct h2_request *r, void *pool,
                                          const char *name, size_t nlen,
                                          const char *value, size_t vlen,
                                          int max_field_len, int *pwas_added)
{
    (void)r; (void)pool; (void)name; (void)nlen; (void)value; (void)vlen;
    (void)max_field_len;
    *pwas_added = 0;
    return g_add_header_status;
}

